export function SecondaryButton({
  label = "{{label}}",
  size = "{{size}}",
  bg = "{{bg}}",
  radius = {{radius}},
  disabled = {{disabled}},
}) {
  const lg = size === "lg";
  return (
    <button
      type="button"
      disabled={disabled}
      style={{
        padding: lg ? "14px 26px" : "11px 20px",
        fontSize: lg ? 16 : 15,
        borderRadius: radius,
        border: `2px solid ${bg}`,
        background: "transparent",
        color: bg,
        fontWeight: 600,
        cursor: disabled ? "not-allowed" : "pointer",
        opacity: disabled ? 0.45 : 1,
      }}
    >
      {label}
    </button>
  );
}
